struct Heartbeat{status:Arc<Status>,thread:Option<thread::JoinHandle<()>>}
impl Heartbeat{fn new(log:&Log)->Self{let status=Arc::new(Status{phase:Mutex::new("자료 준비"),last_frame:Mutex::new(Instant::now()),frames:AtomicU64::new(0),done:AtomicBool::new(false)});let(s,l)=(status.clone(),log.clone());let handle=thread::spawn(move||{let mut report=Instant::now();while !s.done.load(Ordering::SeqCst){thread::park_timeout(Duration::from_secs(1));if report.elapsed()>=Duration::from_secs(5)&&s.last_frame.lock().unwrap().elapsed()>=Duration::from_secs(5){l.line(format!("대기 진단 단계={} frames={} · Ctrl+C/자체창 닫기로 종료",*s.phase.lock().unwrap(),s.frames.load(Ordering::SeqCst)));report=Instant::now();}}});Self{status,thread:Some(handle)}}}
impl Drop for Heartbeat{fn drop(&mut self){self.status.done.store(true,Ordering::SeqCst);if let Some(t)=self.thread.take(){t.thread().unpark();let _=t.join();}}}
struct Eye{targets:Vec<Target>,swapchain:xr::Swapchain<xr::D3D11>,width:u32,height:u32}
enum Outcome{Quit,Restart}
#[derive(Debug,PartialEq)]enum StateStep{Begin,EndAndWait,EndAndQuit,Quit,Restart,None}
fn state_step(state:xr::SessionState,running:bool,stop:bool)->StateStep{match state{xr::SessionState::READY if !running=>StateStep::Begin,xr::SessionState::STOPPING=>if stop{StateStep::EndAndQuit}else{StateStep::EndAndWait},xr::SessionState::EXITING|xr::SessionState::LOSS_PENDING=>if stop{StateStep::Quit}else{StateStep::Restart},_=>StateStep::None}}
struct Resume{time:f64,playing:bool,speed:f64,scale:f32,height:f32}
impl Default for Resume{fn default()->Self{Self{time:1800.0,playing:false,speed:1.0,scale:1.0,height:0.76}}}
#[cfg(test)]mod tests{use super::*;#[test]fn stopping_preserves_application(){assert_eq!(state_step(xr::SessionState::STOPPING,true,false),StateStep::EndAndWait);assert_eq!(state_step(xr::SessionState::READY,false,false),StateStep::Begin);assert_eq!(state_step(xr::SessionState::STOPPING,true,true),StateStep::EndAndQuit);assert_eq!(state_step(xr::SessionState::EXITING,false,false),StateStep::Restart);assert_eq!(state_step(xr::SessionState::EXITING,false,true),StateStep::Quit);}}
